*/
scwin.tx_fn_SearchRspnDetail = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — eduRspnStaff.do", unresolved: "action:eduRspnStaff.do" };
};

/**
 * @method
 * @name scwin.tx_fn_SearchChrgDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_SearchChrgDetail = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — eduChrgStaff.do", unresolved: "action:eduChrgStaff.do" };
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.grd_educationList_fmt_chrgTpNm
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_educationList_fmt_chrgTpNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_educationList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "chrgTpNm") ?? '') : '');
        if (v === '공시책임자') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: chrgTpNm (expression)'), String(data ?? '')) + '</a>'; }
        return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: chrgTpNm (expression)'), String(data ?? '')) + '</a>';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_educationList.chrgTpNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.eduForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'searchSaveEducationList');
    frm.action = 'educationStaff.do';
    $c.util.getComponent('dma_SearchReq').set('SCREN_PROCES_TP_CD', "01");
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchRspnDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param disclsEduApplSeq chrgTpCd disclsBzChrgAssgnDd seq isurCd editAvailYn
 * @returns
 * @hidden N
*/
scwin.searchRspnDetail = async function (disclsEduApplSeq, chrgTpCd, disclsBzChrgAssgnDd, seq, isurCd, editAvailYn) {
    /* sdd-asis-lifecycle:begin fn_SearchRspnDetail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.eduDetailForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'findEducationStaffResponsibilityDetail');
    $c.util.getComponent('dma_SearchReq').set('disclsEduApplSeq', disclsEduApplSeq);
    $c.util.getComponent('dma_SearchReq').set('chrgTpCd', chrgTpCd);
    $c.util.getComponent('dma_SearchReq').set('disclsBzChrgAssgnDd', disclsBzChrgAssgnDd);
    $c.util.getComponent('dma_SearchReq').set('seq', seq);
    $c.util.getComponent('dma_SearchReq').set('txtisurCd', isurCd);
    $c.util.getComponent('dma_SearchReq').set('editAvailYn', editAvailYn);
    frm.action = 'eduRspnStaff.do';
    $c.util.getComponent('dma_SearchReq').set('SCREN_PROCES_TP_CD', "01");
    await scwin.tx_fn_SearchRspnDetail();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchChrgDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param disclsEduApplSeq seq isurCd editAvailYn
 * @returns
 * @hidden N
*/
scwin.searchChrgDetail = async function (disclsEduApplSeq, seq, isurCd, editAvailYn) {
    /* sdd-asis-lifecycle:begin fn_SearchChrgDetail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.eduDetailForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'findEducationStaffChargeDetail');
    $c.util.getComponent('dma_SearchReq').set('disclsEduApplSeq', disclsEduApplSeq);
    $c.util.getComponent('dma_SearchReq').set('seq', seq);
    $c.util.getComponent('dma_SearchReq').set('txtisurCd', isurCd);
    $c.util.getComponent('dma_SearchReq').set('editAvailYn', editAvailYn);
    frm.action = 'eduChrgStaff.do';
    $c.util.getComponent('dma_SearchReq').set('SCREN_PROCES_TP_CD', "01");
    await scwin.tx_fn_SearchChrgDetail();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.findCompany
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.findCompany = async function () {
    /* sdd-asis-lifecycle:begin fn_findCompany — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const corpSearchURL = '/jldfil00033/jldfil00033.xml';
    scwin.setCorpInfo_recv(await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(corpSearchURL), { id: "corpWin", scrollbars: false, resizable: false, width: "600", height: "510", type: "pageFramePopup" }, { method: "loadInitPage" }));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCorpInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param isurCd kisComCd repIsuSrtCd comNm comAbbrv isurSymbl fssUnqNo
 * @returns
 * @hidden N
*/
scwin.setCorpInfo = function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    /* sdd-asis-lifecycle:begin setCorpInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_SearchReq').set('txtisurCd', isurCd);
    $c.util.getComponent('dma_SearchReq').set('txtfssUnqNo', fssUnqNo);
    $c.util.getComponent("ipt_txtcomNm").setValue(comNm);
    $c.util.getComponent('dma_SearchReq').set('tgtIsuSrtCd', repIsuSrtCd);
    $c.util.getComponent('dma_SearchReq').set('chkPop', 'Y');
    /* sdd-asis-lifecycle:end */
};



// 팝업 회신 수신 — 팝업이 남긴 인자를 as-is 함수 인자 순서로 펼쳐 넘긴다.
/**
 * @method
 * @name scwin.setCorpInfo_recv
 * @author Inswave
 * @date 2026. 09. 29
 * @param r
 * @returns
 * @hidden N
*/
scwin.setCorpInfo_recv = function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } };


/**
 * @event
 * @name scwin.krxpage_pagenavigator_108_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_108_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_SearchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_108.page' }); } scwin.search(); };
